def lexicographically_minimum_string(q, test_cases):
    results = []
    for n, k, s in test_cases:
        s = list(s)
        zero_positions = [i for i, char in enumerate(s) if char == '0']
        one_positions = [i for i, char in enumerate(s) if char == '1']

        # Move '0's to the right
        for i, zero_pos in enumerate(zero_positions):
            target_pos = n - len(zero_positions) + i
            if zero_pos != target_pos:
                s[zero_pos], s[target_pos] = s[target_pos], s[zero_pos]
                k -= 1
                if k == 0:
                    break

        # If there are remaining moves, move '1's to the left
        if k > 0:
            for i, one_pos in enumerate(one_positions):
                target_pos = i
                if one_pos != target_pos:
                    s[one_pos], s[target_pos] = s[target_pos], s[one_pos]
                    k -= 1
                    if k == 0:
                        break

        results.append(''.join(s))

    return results

